{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE qcom_inventory_loss_sale_replen AS ( WITH base_payment AS ( SELECT ORDER_NAME, pincode, ORDER_TIMESTAMP, sku FROM fact_items_snitch WHERE ORDER_TIMESTAMP >= DATEADD(day, -15, CURRENT_TIMESTAMP()) AND ORDER_TIMESTAMP < DATEADD(day, 1, CURRENT_TIMESTAMP()) AND ORDER_NAME IS NOT NULL AND (pincode ILIKE \'560%\' OR pincode IS NULL) AND CATEGORY NOT IN (\'PERFUMES\', \'ACCESSORIES\', \'BAGS\', \'SUNGLASSES\', \'SHOES\', \'BELTS\', \'FOOTWEAR\') ), order_qcom_flag AS ( SELECT channel_order_number, BOOLOR_AGG(COALESCE(is_quick_com, FALSE)) AS is_quick_com FROM omni_order_processing_meta GROUP BY channel_order_number ), pincode_branch_map AS ( SELECT shipping_pincode AS pincode, branch_code, COUNT(*) AS qcom_orders FROM omni_order_processing_meta WHERE is_quick_com = TRUE AND branch_code IN (\'13\',\'52\') AND created_at >= DATEADD(day, -30, CURRENT_DATE()) GROUP BY 1,2 ), dominant_pincode_branch AS ( SELECT pincode, branch_code FROM pincode_branch_map QUALIFY ROW_NUMBER() OVER ( PARTITION BY pincode ORDER BY qcom_orders DESC ) = 1 ), eligible_matrix AS ( SELECT DISTINCT op.branch_code AS branch_code, op.shipping_pincode AS pincode, im.sku, category_code FROM omni_order_processing_meta op JOIN omni_inventory_meta im ON im.branch_code = op.branch_code AND im.quick_com_available = TRUE AND im.inventory_total > 1 WHERE op.is_quick_com = TRUE AND op.branch_code IN (\'13\',\'52\') AND op.created_at >= DATEADD(day, -10, CURRENT_DATE()) AND CATEGORY_CODE NOT IN (\'PERFUMES\', \'ACCESSORIES\', \'BAGS\', \'SUNGLASSES\', \'SHOES\', \'BELTS\', \'FOOTWEAR\') ), eligible_pincodes AS ( SELECT DISTINCT pincode FROM eligible_matrix ), joined AS ( SELECT CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.ORDER_TIMESTAMP) AS dt_ist, CASE WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.ORDER_TIMESTAMP)) >= 22 THEN DATEADD(hour, 9, DATEADD(day, 1, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.ORDER_TIMESTAMP)) )) WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.ORDER_TIMESTAMP)) < 10 THEN DATEADD(hour, 9, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.ORDER_TIMESTAMP)) ) ELSE CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.ORDER_TIMESTAMP) END AS created_frozen_ist, p.ORDER_NAME, NULLIF(p.sku,\'\') AS sku, NULLIF(p.pincode,\'\') AS pincode, COALESCE(q.is_quick_com, FALSE) AS is_quick_com, IFF(ep.pincode IS NOT NULL, TRUE, FALSE) AS is_qcom_eligible_pincode, IFF(em.sku IS NOT NULL, TRUE, FALSE) AS is_qcom_eligible FROM base_payment p LEFT JOIN order_qcom_flag q ON q.channel_order_number = p.ORDER_NAME LEFT JOIN eligible_pincodes ep ON ep.pincode = p.pincode LEFT JOIN eligible_matrix em ON em.sku = p.sku AND em.pincode = p.pincode ), filtered AS ( SELECT *, TO_DATE(created_frozen_ist) AS business_date FROM joined WHERE TO_DATE(created_frozen_ist) BETWEEN DATEADD(day, -15, CURRENT_DATE()) AND CURRENT_DATE() ), missed_qcom AS ( SELECT f.business_date, f.order_name, f.sku, pb.branch_code FROM filtered f LEFT JOIN dominant_pincode_branch pb ON pb.pincode = f.pincode WHERE f.is_qcom_eligible_pincode = TRUE AND f.is_qcom_eligible = FALSE AND f.is_quick_com = FALSE ), missed_daily AS ( SELECT sku, branch_code, business_date, COUNT(*) AS missed_cnt FROM missed_qcom WHERE sku IS NOT NULL AND branch_code IS NOT NULL GROUP BY 1,2,3 ), missed_features AS ( SELECT sku, branch_code, SUM(missed_cnt) AS missed_15d, SUM(IFF(business_date >= DATEADD(day, -3, CURRENT_DATE()), missed_cnt, 0)) AS missed_3d, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), missed_cnt, 0)) AS missed_7d, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), missed_cnt, 0)) - SUM(IFF(business_date < DATEADD(day, -7, CURRENT_DATE()) AND business_date >= DATEADD(day, -14, CURRENT_DATE()), missed_cnt, 0)) AS trend_7d_vs_prev7d, COUNT(DISTINCT IFF(missed_cnt > 0, business_date, NULL)) AS active_days_15d, MAX(IFF(missed_cnt > 0, business_date, NULL)) AS last_missed_date, DATEDIFF(\'day\', MAX(IFF(missed_cnt > 0, business_date, NULL)), CURRENT_DATE()) AS days_since_last_missed FROM missed_daily GROUP BY 1,2 ), store_inv_now AS ( SELECT sku, branch_code, SUM(inventory_total) AS store_qty_now FROM omni_inventory_meta WHERE branch_code IN (\'13\',\'52\') AND quick_com_available = TRUE GROUP BY 1,2 ), wh_inv AS ( SELECT \"Item SkuCode\" AS sku, facility, SUM(inventory) AS qty FROM snitch_db.maplemonk.quick_com_live_inv_new WHERE facility IN (\'SAPL-WH1\',\'SAPL-WH2\') GROUP BY 1,2 ), wh_inv_pivot AS ( SELECT sku, SUM(CASE WHEN facility = \'SAPL-WH1\' THEN qty ELSE 0 END) AS wh1_qty_today, SUM(CASE WHEN facility = \'SAPL-WH2\' THEN qty ELSE 0 END) AS wh2_qty_today, SUM(qty) AS wh_total_qty_today FROM wh_inv GROUP BY 1 ), replen_calc AS ( SELECT mf.sku, mf.branch_code, mf.missed_3d, mf.missed_7d, mf.missed_15d, mf.trend_7d_vs_prev7d, mf.active_days_15d, mf.last_missed_date, mf.days_since_last_missed, (0.6 * mf.missed_3d) + (1 * mf.missed_7d) + (0.3 * mf.missed_15d) AS recency_weighted_missed, COALESCE(si.store_qty_now, 0) AS store_qty_now, (mf.missed_7d * 1.0) / 7.0 AS missed_units_per_day_7d, 7 AS cover_days, CEIL(((mf.missed_7d * 1.0) / 7.0) * 7) AS target_units_7d_cover, GREATEST(CEIL(1.0*((mf.missed_7d * 1.0) / 7.0) * 7) - COALESCE(si.store_qty_now, 0), 0) AS suggested_replen_qty FROM missed_features mf LEFT JOIN store_inv_now si ON si.sku = mf.sku AND si.branch_code = mf.branch_code ), replen_filtered AS ( SELECT r.*, IFF( COALESCE(missed_7d, 0) = 0 OR COALESCE(days_since_last_missed, 999) > 7, 0, suggested_replen_qty ) AS suggested_replen_qty_fresh FROM replen_calc r ), qcom_sales_daily AS ( SELECT f.sku, pb.branch_code, f.business_date, COUNT(*) AS sold_units FROM filtered f LEFT JOIN dominant_pincode_branch pb ON pb.pincode = f.pincode WHERE f.is_quick_com = TRUE AND f.sku IS NOT NULL AND pb.branch_code IS NOT NULL GROUP BY 1,2,3 ), qcom_sales_7d AS ( SELECT sku, branch_code, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), sold_units, 0)) AS sold_7d, (SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), sold_units, 0)) * 1.0) / 7.0 AS ros_per_day_7d FROM qcom_sales_daily GROUP BY 1,2 ), ros_oos_replen AS ( SELECT s.sku, s.branch_code, s.sold_7d, s.ros_per_day_7d, COALESCE(si.store_qty_now, 0) AS store_qty_now, IFF(s.ros_per_day_7d > 0, COALESCE(si.store_qty_now, 0) / s.ros_per_day_7d, NULL) AS days_of_cover, 7 AS cover_days, GREATEST(CEIL(s.ros_per_day_7d * 7) - COALESCE(si.store_qty_now, 0), 0) AS ros_replen_qty FROM qcom_sales_7d s LEFT JOIN store_inv_now si ON si.sku = s.sku AND si.branch_code = s.branch_code ), ros_only_rows AS ( SELECT r.sku, r.branch_code, NULL::NUMBER AS missed_3d, NULL::NUMBER AS missed_7d, NULL::NUMBER AS missed_15d, NULL::NUMBER AS trend_7d_vs_prev7d, NULL::NUMBER AS active_days_15d, NULL::DATE AS last_missed_date, NULL::NUMBER AS days_since_last_missed, NULL::NUMBER AS recency_weighted_missed, r.store_qty_now AS store_qty_now, NULL::FLOAT AS missed_units_per_day_7d, r.cover_days AS cover_days, NULL::NUMBER AS target_units_7d_cover, r.ros_replen_qty AS suggested_replen_qty, r.ros_replen_qty AS suggested_replen_qty_fresh FROM ros_oos_replen r LEFT JOIN replen_filtered mf ON mf.sku = r.sku AND mf.branch_code = r.branch_code WHERE r.ros_replen_qty > 0 AND r.ros_per_day_7d > 0 AND r.days_of_cover IS NOT NULL AND r.days_of_cover <= 2 AND COALESCE(mf.suggested_replen_qty_fresh, 0) = 0 ), replen_for_alloc AS ( SELECT sku, branch_code, missed_3d, missed_7d, missed_15d, trend_7d_vs_prev7d, active_days_15d, last_missed_date, days_since_last_missed, recency_weighted_missed, store_qty_now, missed_units_per_day_7d, cover_days, target_units_7d_cover, suggested_replen_qty, suggested_replen_qty_fresh FROM replen_filtered UNION ALL SELECT sku, branch_code, missed_3d, missed_7d, missed_15d, trend_7d_vs_prev7d, active_days_15d, last_missed_date, days_since_last_missed, recency_weighted_missed, store_qty_now, missed_units_per_day_7d, cover_days, target_units_7d_cover, suggested_replen_qty, suggested_replen_qty_fresh FROM ros_only_rows ), alloc AS ( SELECT rf.*, COALESCE(w.wh1_qty_today, 0) AS wh1_qty_today, COALESCE(w.wh2_qty_today, 0) AS wh2_qty_today, COALESCE(w.wh_total_qty_today, 0) AS wh_total_qty_today, SUM(suggested_replen_qty_fresh) OVER (PARTITION BY rf.sku) AS sku_total_need FROM replen_for_alloc rf LEFT JOIN wh_inv_pivot w ON w.sku = rf.sku ), sku_category AS ( SELECT sku, MAX(UPPER(category_code)) AS category_code FROM omni_inventory_meta GROUP BY 1 ), final_alloc AS ( SELECT a.sku, a.branch_code, a.wh1_qty_today, a.wh2_qty_today, a.wh_total_qty_today, a.suggested_replen_qty_fresh, a.sku_total_need, CASE WHEN a.wh_total_qty_today <= 0 THEN 0 WHEN a.sku_total_need <= 0 THEN 0 ELSE LEAST( a.suggested_replen_qty_fresh, CEIL((a.suggested_replen_qty_fresh * 1.0 / a.sku_total_need) * a.wh_total_qty_today) ) END AS final_replen_qty_to_send FROM alloc a LEFT JOIN sku_category sc ON sc.sku = a.sku WHERE a.suggested_replen_qty_fresh > 0 AND a.wh_total_qty_today > 5 AND COALESCE(sc.category_code,\'\') NOT IN (\'PERFUMES\',\'ACCESSORIES\',\'BAGS\',\'SUNGLASSES\',\'SHOES\',\'BELTS\',\'FOOTWEAR\') ), facility_split AS ( SELECT sku, branch_code, \'SAPL-WH2\' AS facility, LEAST(final_replen_qty_to_send, wh2_qty_today) AS allocated_units FROM final_alloc UNION ALL SELECT sku, branch_code, \'SAPL-WH1\' AS facility, LEAST( GREATEST(final_replen_qty_to_send - LEAST(final_replen_qty_to_send, wh2_qty_today), 0), wh1_qty_today ) AS allocated_units FROM final_alloc ) SELECT sku, branch_code, facility, allocated_units FROM facility_split WHERE allocated_units > 0 AND sku NOT ILIKE \'sh0%\' ORDER BY sku, branch_code, facility ); CREATE OR REPLACE Table QCOM_INVENTORY_LOSS_SALE_REPLEN_GGN AS ( WITH params AS ( SELECT 7::INT AS target_cover_days, 3::FLOAT AS oos_threshold_days ), sector29_pincodes AS ( SELECT column1::VARCHAR AS pincode FROM VALUES (\'122007\'),(\'122009\'),(\'122015\'),(\'122003\'),(\'122005\'),(\'122002\'),(\'122001\'),(\'122018\'),(\'122016\'),(\'122011\'), (\'122017\'),(\'110047\'),(\'110038\'),(\'122004\'),(\'110097\'),(\'110061\'),(\'122098\'),(\'122006\'),(\'122101\'),(\'110030\'), (\'110037\'),(\'110070\'),(\'110077\'),(\'110071\'),(\'110074\'),(\'122012\'),(\'110067\'),(\'110075\'),(\'110068\'),(\'110057\'), (\'122505\') ), base_payment AS ( SELECT order_name, pincode::VARCHAR AS pincode, order_timestamp, sku FROM fact_items_snitch WHERE order_timestamp >= DATEADD(day, -21, CURRENT_TIMESTAMP()) AND order_timestamp < DATEADD(day, 1, CURRENT_TIMESTAMP()) AND order_name IS NOT NULL AND category NOT IN (\'PERFUMES\', \'ACCESSORIES\', \'BAGS\', \'SUNGLASSES\', \'SHOES\', \'BELTS\', \'FOOTWEAR\') AND pincode::VARCHAR IN (SELECT pincode FROM sector29_pincodes) ), order_qcom_flag AS ( SELECT channel_order_number, BOOLOR_AGG(COALESCE(is_quick_com, FALSE)) AS is_quick_com FROM omni_order_processing_meta GROUP BY 1 ), eligible_skus_now AS ( SELECT DISTINCT sku FROM omni_inventory_meta WHERE branch_code = \'73\' AND location ILIKE \'BOHQ%\' AND inventory_total > 2 AND sku IS NOT NULL ), orders_enriched AS ( SELECT p.order_name, NULLIF(p.sku,\'\') AS sku, NULLIF(p.pincode,\'\') AS pincode, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', p.order_timestamp) AS dt_ist, CASE WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) >= 22 THEN DATEADD(hour, 9, DATEADD(day, 1, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) )) WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) < 10 THEN DATEADD(hour, 9, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) ) ELSE CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp) END AS created_frozen_ist, TO_DATE( CASE WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) >= 22 THEN DATEADD(hour, 9, DATEADD(day, 1, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) )) WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) < 10 THEN DATEADD(hour, 9, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp)) ) ELSE CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\',p.order_timestamp) END ) AS business_date, COALESCE(q.is_quick_com, FALSE) AS is_quick_com, TRUE AS is_qcom_eligible_pincode, IFF(es.sku IS NOT NULL, TRUE, FALSE) AS is_qcom_eligible FROM base_payment p LEFT JOIN order_qcom_flag q ON q.channel_order_number = p.order_name LEFT JOIN eligible_skus_now es ON es.sku = p.sku ), filtered AS ( SELECT * FROM orders_enriched WHERE business_date BETWEEN DATEADD(day, -21, CURRENT_DATE()) AND CURRENT_DATE() ), missed_qcom AS ( SELECT f.business_date, f.order_name, f.sku, \'73\' AS branch_code FROM filtered f WHERE f.is_qcom_eligible_pincode = TRUE AND f.is_qcom_eligible = FALSE AND f.is_quick_com = FALSE ), missed_daily AS ( SELECT sku, branch_code, business_date, COUNT(*) AS missed_cnt FROM missed_qcom WHERE sku IS NOT NULL GROUP BY 1,2,3 ), missed_features AS ( SELECT sku, branch_code, SUM(missed_cnt) AS missed_15d, SUM(IFF(business_date >= DATEADD(day, -3, CURRENT_DATE()), missed_cnt, 0)) AS missed_3d, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), missed_cnt, 0)) AS missed_7d, MAX(IFF(missed_cnt > 0, business_date, NULL)) AS last_missed_date, DATEDIFF(\'day\', MAX(IFF(missed_cnt > 0, business_date, NULL)), CURRENT_DATE()) AS days_since_last_missed FROM missed_daily GROUP BY 1,2 ), demand_daily AS ( SELECT sku, \'73\' AS branch_code, business_date, COUNT(*) AS ord_cnt FROM filtered WHERE sku IS NOT NULL GROUP BY 1,2,3 ), demand_features AS ( SELECT sku, branch_code, SUM(IFF(business_date >= DATEADD(day, -3, CURRENT_DATE()), ord_cnt, 0)) AS demand_3d, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), ord_cnt, 0)) AS demand_7d FROM demand_daily GROUP BY 1,2 ), sku_universe AS ( SELECT DISTINCT sku, branch_code FROM missed_features UNION SELECT DISTINCT sku, branch_code FROM demand_features ), store_inv_now AS ( SELECT sku, branch_code, SUM(inventory_total) AS store_qty_now FROM omni_inventory_meta WHERE branch_code = \'73\' AND quick_com_available = TRUE GROUP BY 1,2 ), intransit_tauru_to_sector29 AS ( SELECT b.sku, \'73\' AS branch_code, COUNT(*) AS intransit_qty FROM warehouse_b2b_performance b WHERE b.INWARD_TYPE = \'Q-Comm\' AND b.store = \'SNITCH - COCO - SECTOR-29\' AND b.final_status IN (\'INTRANSIT\', \'PICKUPPENDING\') AND b.warehouse_name IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH1\', \'SAPL-WH2\') AND ORDER_NAME NOT IN (\'QC-SECTOR10708\', \'QC-SECTOR10901\') GROUP BY 1,2 ), store_position AS ( SELECT su.sku, su.branch_code, COALESCE(si.store_qty_now, 0) AS store_qty_now, COALESCE(it.intransit_qty, 0) AS intransit_qty, COALESCE(si.store_qty_now, 0) + COALESCE(it.intransit_qty, 0) AS effective_store_qty FROM sku_universe su LEFT JOIN store_inv_now si ON si.sku = su.sku AND si.branch_code = su.branch_code LEFT JOIN intransit_tauru_to_sector29 it ON it.sku = su.sku AND it.branch_code = su.branch_code ), replen_calc AS ( SELECT mf.sku, mf.branch_code, mf.missed_3d, mf.missed_7d, mf.missed_15d, mf.days_since_last_missed, sp.effective_store_qty, 7 AS cover_days, CEIL(((mf.missed_7d * 1.0) / 7.0) * 7) AS target_units_7d_cover, GREATEST( CEIL(((mf.missed_7d * 1.0) / 7.0) * 7) - COALESCE(sp.effective_store_qty, 0), 0 ) AS suggested_replen_qty FROM missed_features mf LEFT JOIN store_position sp ON sp.sku = mf.sku AND sp.branch_code = mf.branch_code ), replen_filtered AS ( SELECT r.*, IFF( COALESCE(missed_15d, 0) < 2 OR COALESCE(days_since_last_missed, 999) > 14, 0, suggested_replen_qty ) AS suggested_replen_qty_fresh FROM replen_calc r ), oos_calc AS ( SELECT df.sku, df.branch_code, COALESCE(sp.effective_store_qty, 0) AS effective_store_qty, COALESCE(df.demand_7d, 0) AS demand_7d, (COALESCE(df.demand_7d, 0) / 7.0) AS avg_daily_demand, IFF( (COALESCE(df.demand_7d, 0) / 7.0) > 0, COALESCE(sp.effective_store_qty, 0) / (COALESCE(df.demand_7d, 0) / 7.0), NULL ) AS days_of_cover FROM demand_features df LEFT JOIN store_position sp ON sp.sku = df.sku AND sp.branch_code = df.branch_code ), oos_replen AS ( SELECT oc.sku, oc.branch_code, oc.days_of_cover, CEIL(oc.avg_daily_demand * p.target_cover_days) AS target_units_cover, GREATEST( CEIL(oc.avg_daily_demand * p.target_cover_days) - COALESCE(oc.effective_store_qty, 0), 0 ) AS suggested_replen_qty_oos FROM oos_calc oc CROSS JOIN params p WHERE oc.avg_daily_demand > 0 AND oc.days_of_cover IS NOT NULL AND oc.days_of_cover <= p.oos_threshold_days ), combined_replen AS ( SELECT sku, branch_code, MAX(suggested_qty) AS suggested_replen_qty FROM ( SELECT sku, branch_code, suggested_replen_qty_fresh AS suggested_qty FROM replen_filtered WHERE COALESCE(suggested_replen_qty_fresh, 0) > 0 UNION ALL SELECT sku, branch_code, suggested_replen_qty_oos AS suggested_qty FROM oos_replen WHERE COALESCE(suggested_replen_qty_oos, 0) > 0 ) GROUP BY 1,2 ), wh_inv AS ( SELECT \"Item SkuCode\" AS sku, facility, SUM(inventory) AS qty FROM snitch_db.maplemonk.quick_com_live_inv_new WHERE facility = \'SAPL-NORTH-TAURU\' GROUP BY 1,2 ), wh_inv_pivot AS ( SELECT sku, SUM(qty) AS north_qty_today FROM wh_inv GROUP BY 1 ), final_qty AS ( SELECT cr.sku, cr.branch_code, COALESCE(w.north_qty_today, 0) AS north_qty_today, CASE WHEN COALESCE(w.north_qty_today, 0) <= 0 THEN 0 ELSE LEAST(cr.suggested_replen_qty, COALESCE(w.north_qty_today, 0)) END AS allocated_units FROM combined_replen cr LEFT JOIN wh_inv_pivot w ON w.sku = cr.sku WHERE COALESCE(w.north_qty_today, 0) > 5 ) SELECT sku, branch_code, \'SAPL-NORTH-TAURU\' AS facility, allocated_units FROM final_qty WHERE allocated_units > 0 AND sku NOT ILIKE \'sh0%\' ORDER BY allocated_units DESC, sku ); CREATE OR REPLACE Table QCOM_INVENTORY_LOSS_SALE_REPLEN_GGN_1 AS WITH params AS ( SELECT 30 AS lookback_days_sales, 7 AS lt_wh_to_store_days, 10 AS cover_days, 5 AS min_wh_qty_threshold ), sector29_pincodes AS ( SELECT column1::VARCHAR AS pincode FROM VALUES (\'122007\'),(\'122009\'),(\'122015\'),(\'122003\'),(\'122005\'),(\'122002\'),(\'122001\'),(\'122018\'), (\'122016\'),(\'122011\'),(\'122017\'),(\'110047\'),(\'110038\'),(\'122004\'),(\'110097\'),(\'110061\'), (\'122098\'),(\'122006\'),(\'122101\'),(\'110030\'),(\'110037\'),(\'110070\'),(\'110077\'),(\'110071\'), (\'110074\'),(\'122012\'),(\'110067\'),(\'110075\'),(\'110068\'),(\'110057\'),(\'122505\') ), base_payment AS ( SELECT order_name, pincode::VARCHAR AS pincode, order_timestamp, sku FROM fact_items_snitch JOIN params p ON 1=1 WHERE order_timestamp >= DATEADD(day, -p.lookback_days_sales, CURRENT_TIMESTAMP()) AND order_timestamp < DATEADD(day, 1, CURRENT_TIMESTAMP()) AND order_name IS NOT NULL AND category NOT IN (\'PERFUMES\', \'ACCESSORIES\', \'BAGS\', \'SUNGLASSES\', \'SHOES\', \'BELTS\', \'FOOTWEAR\') AND pincode::VARCHAR IN (SELECT pincode FROM sector29_pincodes) ), order_qcom_flag AS ( SELECT channel_order_number, BOOLOR_AGG(COALESCE(is_quick_com, FALSE)) AS is_quick_com FROM omni_order_processing_meta GROUP BY 1 ), eligible_skus_now AS ( SELECT DISTINCT sku FROM omni_inventory_meta WHERE branch_code = \'73\' AND quick_com_available = true AND inventory_total > 1 AND sku IS NOT NULL ), joined AS ( SELECT CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp) AS dt_ist, CASE WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp)) >= 22 THEN DATEADD(hour, 9, DATEADD(day, 1, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp))) ) WHEN EXTRACT(HOUR FROM CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp)) < 10 THEN DATEADD(hour, 9, DATE_TRUNC(\'DAY\', CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp))) ELSE CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', bp.order_timestamp) END AS created_frozen_ist, bp.order_name, NULLIF(bp.sku,\'\') AS sku, NULLIF(bp.pincode,\'\') AS pincode, COALESCE(qf.is_quick_com, FALSE) AS is_quick_com, TRUE AS is_qcom_eligible_pincode, IFF(es.sku IS NOT NULL, TRUE, FALSE) AS is_qcom_eligible FROM base_payment bp LEFT JOIN order_qcom_flag qf ON qf.channel_order_number = bp.order_name LEFT JOIN eligible_skus_now es ON es.sku = bp.sku ), filtered AS ( SELECT *, TO_DATE(created_frozen_ist) AS business_date FROM joined JOIN params p ON 1=1 WHERE TO_DATE(created_frozen_ist) BETWEEN DATEADD(day, -p.lookback_days_sales, CURRENT_DATE()) AND CURRENT_DATE() ), missed_qcom AS ( SELECT f.business_date, f.order_name, f.sku, \'73\' AS branch_code FROM filtered f WHERE f.is_qcom_eligible_pincode = TRUE AND f.is_qcom_eligible = FALSE AND f.is_quick_com = FALSE ), missed_daily AS ( SELECT sku, branch_code, business_date, COUNT(*) AS missed_cnt FROM missed_qcom WHERE sku IS NOT NULL GROUP BY 1,2,3 ), missed_features AS ( SELECT sku, branch_code, SUM(missed_cnt) AS missed_30d, SUM(IFF(business_date >= DATEADD(day, -7, CURRENT_DATE()), missed_cnt, 0)) AS missed_7d, SUM(IFF(business_date >= DATEADD(day, -15, CURRENT_DATE()), missed_cnt, 0)) AS missed_15d, MAX(IFF(missed_cnt > 0, business_date, NULL)) AS last_missed_date, DATEDIFF(\'day\', MAX(IFF(missed_cnt > 0, business_date, NULL)), CURRENT_DATE()) AS days_since_last_missed FROM missed_daily GROUP BY 1,2 ), store_inv_now AS ( SELECT sku, branch_code, SUM(inventory_total) AS store_qty_now FROM omni_inventory_meta WHERE branch_code = \'73\' AND quick_com_available = TRUE GROUP BY 1,2 ), need_calc AS ( SELECT mf.sku, mf.branch_code, mf.missed_7d, mf.missed_30d, mf.missed_15d, mf.days_since_last_missed, COALESCE(si.store_qty_now, 0) AS store_qty_now, IFF( COALESCE(mf.missed_30d, 0) = 0 OR COALESCE(mf.days_since_last_missed, 999) > 21, 0, GREATEST( CEIL(((mf.missed_30d * 1.0) / 30.0) * (SELECT cover_days FROM params)) - COALESCE(si.store_qty_now, 0), 0 ) ) AS need_qty FROM missed_features mf LEFT JOIN store_inv_now si ON si.sku = mf.sku AND si.branch_code = mf.branch_code ), need_base AS ( SELECT sku, branch_code, need_qty FROM need_calc WHERE need_qty > 0 AND sku NOT ILIKE \'sh0%\' ), wh_onhand AS ( SELECT \"Item SkuCode\" AS sku, facility, SUM(inventory) AS qty FROM snitch_db.maplemonk.quick_com_live_inv_new WHERE facility IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH1\', \'SAPL-WH2\') GROUP BY 1,2 ), north_onhand AS ( SELECT sku, SUM(qty) AS north_qty_today FROM wh_onhand WHERE facility = \'SAPL-NORTH-TAURU\' GROUP BY 1 ), wh2_onhand AS ( SELECT sku, SUM(qty) AS wh2_qty_today FROM wh_onhand WHERE facility = \'SAPL-WH2\' GROUP BY 1 ), wh1_onhand AS ( SELECT sku, SUM(qty) AS wh1_qty_today FROM wh_onhand WHERE facility = \'SAPL-WH1\' GROUP BY 1 ), south_pool AS ( SELECT nb.sku, nb.branch_code, nb.need_qty, COALESCE(n.north_qty_today, 0) AS north_qty_today FROM need_base nb LEFT JOIN north_onhand n ON n.sku = nb.sku WHERE COALESCE(n.north_qty_today, 0) <= (SELECT min_wh_qty_threshold FROM params) ), intransit_wh_to_sector29 AS ( SELECT B.SKU, \'73\' AS branch_code, b.warehouse_name AS facility, COUNT(*) AS intransit_qty FROM warehouse_b2b_performance b WHERE b.INWARD_TYPE = \'Q-Comm\' AND b.store = \'SNITCH - COCO - SECTOR-29\' AND b.final_status IN (\'INTRANSIT\', \'PICKUPPENDING\') AND b.warehouse_name IN (\'SAPL-NORTH-TAURU\',\'SAPL-WH1\',\'SAPL-WH2\') GROUP BY 1,2,3 ), intransit_total AS ( SELECT sku, branch_code, SUM(intransit_qty) AS intransit_qty_total FROM intransit_wh_to_sector29 GROUP BY 1,2 ), south_pool_net AS ( SELECT sp.sku, sp.branch_code, sp.need_qty, COALESCE(it.intransit_qty_total, 0) AS intransit_qty_total, GREATEST(sp.need_qty - COALESCE(it.intransit_qty_total, 0), 0) AS net_need_qty FROM south_pool sp LEFT JOIN intransit_total it ON it.sku = sp.sku AND it.branch_code = sp.branch_code WHERE GREATEST(sp.need_qty - COALESCE(it.intransit_qty_total, 0), 0) > 0 ), wh2_alloc AS ( SELECT sn.sku, sn.branch_code, \'SAPL-WH2\' AS facility, CASE WHEN COALESCE(w2.wh2_qty_today, 0) > (SELECT min_wh_qty_threshold FROM params) THEN LEAST(sn.net_need_qty, w2.wh2_qty_today) ELSE 0 END AS allocated_units FROM south_pool_net sn LEFT JOIN wh2_onhand w2 ON w2.sku = sn.sku ), after_wh2 AS ( SELECT sn.sku, sn.branch_code, GREATEST(sn.net_need_qty - COALESCE(a2.allocated_units, 0), 0) AS remaining_qty FROM south_pool_net sn LEFT JOIN wh2_alloc a2 ON a2.sku = sn.sku AND a2.branch_code = sn.branch_code WHERE GREATEST(sn.net_need_qty - COALESCE(a2.allocated_units, 0), 0) > 0 ), wh1_alloc AS ( SELECT aw.sku, aw.branch_code, \'SAPL-WH1\' AS facility, CASE WHEN COALESCE(w1.wh1_qty_today, 0) > (SELECT min_wh_qty_threshold FROM params) THEN LEAST(aw.remaining_qty, w1.wh1_qty_today) ELSE 0 END AS allocated_units FROM after_wh2 aw LEFT JOIN wh1_onhand w1 ON w1.sku = aw.sku ) SELECT sku, branch_code, facility, allocated_units FROM wh2_alloc WHERE allocated_units > 0 UNION ALL SELECT sku, branch_code, facility, allocated_units FROM wh1_alloc WHERE allocated_units > 0 ORDER BY allocated_units DESC, sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            